import { readFileSync, writeFileSync } from "node:fs";

const files: Record<string, { prefix: "bun" | "node"; react: boolean; fileOpsNum: string }> = {
  "rules/Bun.md": { prefix: "bun", react: false, fileOpsNum: "8.4" },
  "rules/Bun+React+Tailwind.md": { prefix: "bun", react: true, fileOpsNum: "8.3" },
  "rules/NodeJS+React.md": { prefix: "node", react: true, fileOpsNum: "8.4" },
  "rules/NodeJS+React+Tailwind.md": { prefix: "node", react: true, fileOpsNum: "8.4" },
};

for (const [path, cfg] of Object.entries(files)) {
  let raw = readFileSync(path, "utf8");
  const p = cfg.prefix;

  // 1) Trim 8.1 to server-only concerns
  const old81 = `- Use ES6 imports, not CommonJS
- Use fs/promises for file operations
- Graceful shutdown with signal handlers; never call process.exit() directly
- Validate env variables at startup
- Use \`${p}:\` protocol prefix for built-in modules
- Extend Error class for custom errors with context properties
- Await promises before returning for complete stack traces
- Subscribe to 'error' events on EventEmitters and streams
`;
  const new81 = cfg.react
    ? `- Graceful shutdown with signal handlers; never call process.exit() directly\n`
    : `- Graceful shutdown with signal handlers; never call process.exit() directly\n- Validate env variables at startup\n`;
  if (!raw.includes(old81)) throw new Error(`${path}: 8.1 block not found`);
  raw = raw.replace(old81, new81);

  // 2) React files: env validation joins 6.3 Environment Variables
  if (cfg.react) {
    const envAnchor = "- Use .env.example as template\n";
    if (!raw.includes(envAnchor)) throw new Error(`${path}: env anchor not found`);
    raw = raw.replace(envAnchor, `${envAnchor}- Validate env variables at startup\n`);
  }

  // 3) Import rules gain ES6 + protocol prefix
  const importAnchor = "- Import order: builtin → external → internal → parent → sibling\n";
  if (!raw.includes(importAnchor)) throw new Error(`${path}: import anchor not found`);
  raw = raw.replace(
    importAnchor,
    `${importAnchor}- Use ES6 imports, never CommonJS require()\n- Use \`${p}:\` protocol prefix for built-in modules\n`,
  );

  // 4) JavaScript section gains the error-handling trio
  const jsAnchor = "- Use early returns (fail fast) instead of nested else\n";
  if (!raw.includes(jsAnchor)) throw new Error(`${path}: js anchor not found`);
  raw = raw.replace(
    jsAnchor,
    `${jsAnchor}- Extend Error class for custom errors with context properties\n- Await promises before returning for complete stack traces\n- Subscribe to 'error' events on EventEmitters and streams\n`,
  );

  // 5) Move File Operations from §8 to §6 (after TypeScript / Env Variables)
  const fileOpsBlock = `### ${cfg.fileOpsNum} File Operations

- Use \`${p}:fs/promises\` for files < 100MB
- Use streams for files > 100MB
- Use \`pipeline()\` for stream chaining
- Use \`import.meta.dirname\` for module-relative paths
- Handle error codes: ENOENT, EACCES, etc.
- Always close file handles in finally blocks

`;
  if (!raw.includes(fileOpsBlock)) throw new Error(`${path}: file-ops block not found`);
  raw = raw.replace(fileOpsBlock, "");
  const newNum = cfg.react ? "6.4" : "6.3";
  const moved = fileOpsBlock.replace(`### ${cfg.fileOpsNum} `, `### ${newNum} `);
  raw = raw.replace(/(?=## 7\. |## 8\. Server-Side Standards)/, moved);

  writeFileSync(path, raw);
  console.log(`✓ ${path}`);
}
EOF
